package com.library.server.interceptor;
import com.library.common.annotation.RequireRole; import com.library.common.model.LoginUser; import com.library.common.exception.UnauthorizedException; import com.library.common.util.JwtUtil; import com.library.server.util.UserContext; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.stereotype.Component; import org.springframework.web.method.HandlerMethod; import org.springframework.web.servlet.HandlerInterceptor;
@Component public class AuthInterceptor implements HandlerInterceptor { private final JwtUtil jwtUtil; public AuthInterceptor(JwtUtil jwtUtil){this.jwtUtil=jwtUtil;}
 @Override public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler){ if(!(handler instanceof HandlerMethod method)) return true; String header=req.getHeader("Authorization"); if(header==null||!header.startsWith("Bearer ")) throw new UnauthorizedException("请先登录"); LoginUser user=jwtUtil.parse(header.substring(7)); if(user==null) throw new UnauthorizedException("登录已过期"); UserContext.set(user); RequireRole role=method.getMethodAnnotation(RequireRole.class); if(role==null) role=method.getBeanType().getAnnotation(RequireRole.class); if(role!=null){boolean allowed=false; for(String item:role.value()) if(item.equals(user.getRole())) allowed=true; if(!allowed) throw new com.library.common.exception.BusinessException("无权访问");} return true; }
 @Override public void afterCompletion(HttpServletRequest req,HttpServletResponse res,Object handler,Exception ex){UserContext.clear();}
}
